bool extract_socket_address_and_port(struct pool *pool, char *url) {
    char *url_start = url;
    char *address_end = NULL;
    char *port_start = NULL;
    int port = 0;
    bool success = false;

    // Skip the protocol (e.g., "http://", "https://", etc.)
    if (strncmp(url, "http://", 7) == 0) {
        url_start += 7;
    } else if (strncmp(url, "https://", 8) == 0) {
        url_start += 8;
    } else {
        return false; // Unsupported protocol
    }

    // Check for IPv6 address wrapped in brackets
    if (*url_start == '[') {
        url_start++; // Skip opening bracket
        address_end = strchr(url_start, ']');
        if (!address_end) {
            return false; // Malformed IPv6 address
        }
        // Check for port after IPv6
        if (*(address_end + 1) == ':') {
            port_start = address_end + 2;
        }
    } else {
        // Find the end of the address for IPv4
        address_end = url_start;
        while (*address_end && *address_end != ':') {
            address_end++;
        }
    }

    // Ensure we found a valid address
    if (!address_end || address_end == url_start) {
        return false;
    }

    // Determine the port
    if (port_start) {
        port = atoi(port_start);
    } else {
        port = 80; // Default HTTP port
    }

    // Calculate the length of the address string
    size_t address_length = address_end - url_start;
    if (address_length == 0) {
        return false; // No address found
    }

    // Allocate memory in the pool for the socket address
    pool->socket_address = (char *)malloc(address_length + 1);
    if (!pool->socket_address) {
        return false; // Memory allocation failed
    }

    // Copy the address into the pool
    strncpy(pool->socket_address, url_start, address_length);
    pool->socket_address[address_length] = '\0';

    // Set the port in the pool
    pool->port = port;

    success = true;
    return success;
}

bool extract_socket_address_and_port(struct pool *pool, char *url) {
    char *start = url;
    char *end = NULL;
    char *port_start = NULL;
    char *address = NULL;
    int port = 0;
    bool is_ipv6 = false;

    if (!url || !pool) {
        return false;
    }

    // Check for IPv6 address in brackets
    if (*start == '[') {
        start++;
        is_ipv6 = true;
        end = strchr(start, ']');
        if (!end) {
            return false;
        }
        // Check for port after the closing bracket
        if (*(end + 1) == ':') {
            port_start = end + 2;
        }
    } else {
        // Regular IPv4 or hostname
        end = strchr(start, ':');
        if (end && *(end + 1) == ':') {
            port_start = end + 2;
        } else {
            end = strchr(start, '/');
        }
    }

    if (!end) {
        return false;
    }

    // Copy address to buffer
    size_t address_len = end - start;
    address = (char *)malloc(address_len + 1);
    if (!address) {
        return false;
    }
    memcpy(address, start, address_len);
    address[address_len] = '\0';

    // Set default port if none specified
    if (!port_start) {
        port = 80;  // default port
    } else {
        port = atoi(port_start);
    }

    // Update the pool structure
    pool->socket_address = address;
    pool->port = port;

    return true;
}

bool extract_socket_address_and_port(struct pool *pool, char *url) {
    char *start = url;
    char *end = NULL;
    char *colon = NULL;
    char *address_end = NULL;
    char buffer[128];
    int port = 0;
    bool success = false;

    if (!url || !pool) {
        return false;
    }

    if (*start == '[') {
        start++;
        address_end = strchr(start, ']');
        if (!address_end) {
            return false;
        }
        address_end++;  // Move to the colon
    }

    colon = strchr(start, ':');
    if (!colon) {
        // Default port if none specified
        port = 80;
    } else {
        // Try to parse the port
        char *port_str = colon + 1;
        char *endptr;
        port = (int)strtol(port_str, &endptr, 10);
        if (endptr == port_str || *endptr != '\0') {
            return false;
        }
    }

    if (address_end) {
        address_end = start;
    }

    if (colon) {
        // Limit the address to the part before the port
        size_t address_len = colon - start;
        if (address_len >= sizeof(buffer)) {
            return false;
        }
        memcpy(buffer, start, address_len);
        buffer[address_len] = '\0';
        address_end = buffer;
    } else {
        // No port, use the whole URL as the address
        size_t url_len = strlen(start);
        if (url_len >= sizeof(buffer)) {
            return false;
        }
        memcpy(buffer, start, url_len);
        buffer[url_len] = '\0';
        address_end = buffer;
    }

    pool->socket_address = strdup(address_end);
    pool->port = port;

    if (pool->socket_address) {
        success = true;
    }

    return success;
}

bool extract_socket_address_from_url(struct pool *pool, char *url) {
    char *start, *end, *colon, *host_end;
    char *buf;
    size_t len;

    if (url == NULL || *url == '\0') {
        return false;
    }

    start = url;
    if (*start == '[') { /* IPv6 address */
        start++;
        end = strchr(start, ']');
        if (end == NULL) {
            return false;
        }
        host_end = end + 1;
    } else {
        host_end = start;
        while (*host_end && *host_end != ':') {
            host_end++;
        }
    }

    len = host_end - start;
    if (len == 0) {
        return false;
    }

    buf = pool_alloc(pool, len + 1);
    if (buf == NULL) {
        return false;
    }

    strncpy(buf, start, len);
    buf[len] = '\0';

    if (host_end[0] == ':') {
        pool->port = atoi(host_end + 1);
    } else {
        pool->port = 80; /* Default port */
    }

    pool->socket_address = buf;
    return true;
}

#include <string.h>
#include <stdbool.h>

bool extract_address_and_port(struct pool *pool, char *url) {
    char *url_start = url;
    char *colon = NULL;
    char *end_of_address = url;
    int port = -1;
    bool is_ipv6 = false;
    char *address_buffer = NULL;

    if (!url || !pool) {
        return false;
    }

    // Check for IPv6 address in brackets
    if (*url_start == '[') {
        url_start++;
        is_ipv6 = true;
        char *closing_bracket = strchr(url_start, ']');
        if (!closing_bracket) {
            return false;
        }
        end_of_address = closing_bracket;
        colon = strchr(closing_bracket + 1, ':');
    } else {
        colon = strchr(url_start, ':');
    }

    if (colon) {
        // Port is present
        char *port_str = colon + 1;
        port = atoi(port_str);
    }

    if (url_start == url || (is_ipv6 && url_start == url + 1)) {
        size_t address_len = end_of_address - url_start;
        address_buffer = (char *)pool_alloc(pool, address_len + 1);
        if (!address_buffer) {
            return false;
        }
        strncpy(address_buffer, url_start, address_len);
        address_buffer[address_len] = '\0';
    } else {
        return false;
    }

    if (port == -1) {
        port = 80; // Default port
    }

    pool->address = address_buffer;
    pool->port = port;

    return true;
}
